-- Official NCA control catalogs. Idempotent import; existing workflow values and assignments are preserved.
select setval(pg_get_serial_sequence('public.controls','id'),coalesce((select max(id) from public.controls),0)+1,false);

-- Source: NCA Cloud Cybersecurity Controls (CCC-2:2024), Arabic and English official documents.
-- Import 175 controls as an unassigned reference catalog.
insert into public.frameworks(code,name_ar,name_en,version,description_ar,is_active)
values ('CCC','ضوابط الأمن السيبراني للحوسبة السحابية','Cloud Cybersecurity Controls','2-2024','متطلبات الأمن السيبراني للحوسبة السحابية من منظور مقدمي الخدمات والمشتركين.',true)
on conflict (code) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,version=excluded.version,description_ar=excluded.description_ar,is_active=true;
with source(control_code,title_ar,description_ar,domain_ar,control_type,source_row) as (values
    ('1-1-P-1', 'أدوار ومسؤوليات الأمن السيبراني (مقدم الخدمة) - 1-1-P-1', 'In addition to the ECC control 1-4-1, the Authorizing Official shall also identify, document, and approve:', 'حوكمة الأمن السيبراني', 'أساسي', '1'),
    ('1-1-P-1-1', 'أدوار ومسؤوليات الأمن السيبراني (مقدم الخدمة) - 1-1-P-1-1', 'Cybersecurity roles and RACI assignment for all stakeholders of the cloud services including the Authorizing Official''s roles and responsibilities', 'حوكمة الأمن السيبراني', 'فرعي', '2'),
    ('1-1-T-1', 'أدوار ومسؤوليات الأمن السيبراني (المشترك) - 1-1-T-1', 'In addition to the ECC control 1-4-1, the Authorizing Official shall also identify, document, and approve:', 'حوكمة الأمن السيبراني', 'أساسي', '3'),
    ('1-1-T-1-1', 'أدوار ومسؤوليات الأمن السيبراني (المشترك) - 1-1-T-1-1', 'Cybersecurity roles and RACI assignment for all stakeholders of the cloud services including the Authorizing Official''s roles and responsibilities.', 'حوكمة الأمن السيبراني', 'فرعي', '4'),
    ('1-2-P-1', 'إدارة مخاطر الأمن السيبراني (مقدم الخدمة) - 1-2-P-1', 'Cybersecurity risk management methodology mentioned in the ECC Subdomain 1-5, shall also include for the CSP, as a minimum:', 'حوكمة الأمن السيبراني', 'أساسي', '5'),
    ('1-2-P-1-1', 'إدارة مخاطر الأمن السيبراني (مقدم الخدمة) - 1-2-P-1-1', 'Defining acceptable risk levels for the cloud services and clarifying them to the CST if they are related to the CST', 'حوكمة الأمن السيبراني', 'فرعي', '6'),
    ('1-2-P-1-2', 'إدارة مخاطر الأمن السيبراني (مقدم الخدمة) - 1-2-P-1-2', 'Considering data and information classification in cybersecurity risk management methodology', 'حوكمة الأمن السيبراني', 'فرعي', '7'),
    ('1-2-P-1-3', 'إدارة مخاطر الأمن السيبراني (مقدم الخدمة) - 1-2-P-1-3', 'Developing cybersecurity risk register for cloud services and monitoring it periodically according to the risks', 'حوكمة الأمن السيبراني', 'فرعي', '8'),
    ('1-2-T-1', 'إدارة مخاطر الأمن السيبراني (المشترك) - 1-2-T-1', 'Cybersecurity risk management methodology mentioned in the ECC Subdomain 1-5 shall also include for the CST, as a minimum:', 'حوكمة الأمن السيبراني', 'أساسي', '9'),
    ('1-2-T-1-1', 'إدارة مخاطر الأمن السيبراني (المشترك) - 1-2-T-1-1', 'Defining acceptable risk levels for the cloud services', 'حوكمة الأمن السيبراني', 'فرعي', '10'),
    ('1-2-T-1-2', 'إدارة مخاطر الأمن السيبراني (المشترك) - 1-2-T-1-2', 'Considering data and information classification accredited by CST in cybersecurity risk management methodology', 'حوكمة الأمن السيبراني', 'فرعي', '11'),
    ('1-2-T-1-3', 'إدارة مخاطر الأمن السيبراني (المشترك) - 1-2-T-1-3', 'Developing cybersecurity risk register for cloud services and monitoring it periodically according to the risks. مقيد - محدود', 'حوكمة الأمن السيبراني', 'فرعي', '12'),
    ('1-3-P-1', 'الالتزام بتشريعات ومعايير وضوابط الأمن السيبراني (مقدم الخدمة) - 1-3-P-1', 'In addition to the ECC control 1-7-1, the CSP legislative and regulatory compliance should include as a minimum with the following requirements:', 'حوكمة الأمن السيبراني', 'أساسي', '13'),
    ('1-3-P-1-1', 'الالتزام بتشريعات ومعايير وضوابط الأمن السيبراني (مقدم الخدمة) - 1-3-P-1-1', 'Continuous compliance with all laws, regulations, instructions, decisions, regulatory frameworks and controls, and mandates regarding cybersecurity in the Kingdom', 'حوكمة الأمن السيبراني', 'فرعي', '14'),
    ('1-3-T-1', 'الالتزام بتشريعات ومعايير وضوابط الأمن السيبراني (المشترك) - 1-3-T-1', 'In addition to the ECC control 1-7-1, the CST legislative and regulatory compliance should include as a minimum with the following requirements:', 'حوكمة الأمن السيبراني', 'أساسي', '15'),
    ('1-3-T-1-1', 'الالتزام بتشريعات ومعايير وضوابط الأمن السيبراني (المشترك) - 1-3-T-1-1', 'Continuous or real-time compliance monitoring of the CSP with relevant cybersecurity legislation and contract clauses.', 'حوكمة الأمن السيبراني', 'فرعي', '16'),
    ('1-4-P-1', 'الأمن السيبراني المتعلق بالموارد البشرية (مقدم الخدمة) - 1-4-P-1', 'In addition to Subcontrols in the ECC controls 1-9-3 and 1-9-4, the following requirements should be covered prior and during the professional relationship of personnel with the CSP as a minimum:', 'حوكمة الأمن السيبراني', 'أساسي', '17'),
    ('1-4-P-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية (مقدم الخدمة) - 1-4-P-1-1', 'Positions of cybersecurity functions in CSP’s data centers within the Kingdom must be filled with qualified and suitable Saudi nationals', 'حوكمة الأمن السيبراني', 'فرعي', '18'),
    ('1-4-P-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية (مقدم الخدمة) - 1-4-P-1-2', 'Screening or vetting candidates of personnel working inside the Kingdom who have access to Cloud Technology Stack, periodically', 'حوكمة الأمن السيبراني', 'فرعي', '19'),
    ('1-4-P-1-3', 'الأمن السيبراني المتعلق بالموارد البشرية (مقدم الخدمة) - 1-4-P-1-3', 'Cybersecurity policies as a prerequisite to access to Cloud Technology Stack, signed and appropriately approved', 'حوكمة الأمن السيبراني', 'فرعي', '20'),
    ('1-4-P-2', 'الأمن السيبراني المتعلق بالموارد البشرية (مقدم الخدمة) - 1-4-P-2', 'In addition to Subcontrols in the ECC control 1-9-5, the following requirements should be in place, as a minimum, for the termination/completion of a human resource’s professional relationship with the CSP:', 'حوكمة الأمن السيبراني', 'أساسي', '21'),
    ('1-4-P-2-1', 'الأمن السيبراني المتعلق بالموارد البشرية (مقدم الخدمة) - 1-4-P-2-1', 'Assurance that assets owned by the entity (especially those with security exposure) are accounted for and returned upon termination', 'حوكمة الأمن السيبراني', 'فرعي', '22'),
    ('1-4-T-1', 'الأمن السيبراني المتعلق بالموارد البشرية (المشترك) - 1-4-T-1', 'In addition to Subcontrols in the ECC control 1-9-3, the following requirements should be covered prior the professional relationship of staff with the CST shall cover, at a minimum:', 'حوكمة الأمن السيبراني', 'أساسي', '23'),
    ('1-4-T-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية (المشترك) - 1-4-T-1-1', 'Screening or vetting candidates of personnel with access to Cloud Service sensitive functions (Key Management, Service Administration, Access Control). مقيد - محدود', 'حوكمة الأمن السيبراني', 'فرعي', '24'),
    ('1-5-P-1', 'الأمن السيبراني ضمن إدارة التغيير (مقدم الخدمة) - 1-5-P-1', 'Cybersecurity requirements for change management within the CSP shall be identified, documented, and approved', 'حوكمة الأمن السيبراني', 'أساسي', '25'),
    ('1-5-P-2', 'الأمن السيبراني ضمن إدارة التغيير (مقدم الخدمة) - 1-5-P-2', 'Cybersecurity requirements for change management within the CSP shall be applied', 'حوكمة الأمن السيبراني', 'أساسي', '26'),
    ('1-5-P-3', 'الأمن السيبراني ضمن إدارة التغيير (مقدم الخدمة) - 1-5-P-3', 'Cybersecurity for change management in the CSP shall cover, as a minimum:', 'حوكمة الأمن السيبراني', 'أساسي', '27'),
    ('1-5-P-3-1', 'الأمن السيبراني ضمن إدارة التغيير (مقدم الخدمة) - 1-5-P-3-1', 'Processes and procedures to securely implement changes (planned works) in production systems, with priority given to cybersecurity observations', 'حوكمة الأمن السيبراني', 'فرعي', '28'),
    ('1-5-P-3-2', 'الأمن السيبراني ضمن إدارة التغيير (مقدم الخدمة) - 1-5-P-3-2', 'Process for the implementation of cybersecurity exceptional changes (e.g.: changes during incident restoration)', 'حوكمة الأمن السيبراني', 'فرعي', '29'),
    ('1-5-P-4', 'الأمن السيبراني ضمن إدارة التغيير (مقدم الخدمة) - 1-5-P-4', 'Cybersecurity requirements for change management within the CSP shall be applied and reviewed periodically. مقيد - محدود Cybersecurity Defense', 'حوكمة الأمن السيبراني', 'أساسي', '30'),
    ('2-1-P-1', 'إدارة الأصول (مقدم الخدمة) - 2-1-P-1', 'In addition to controls in the ECC control 2-1, the CSP shall cover the following additional controls for cybersecurity requirements for cybersecurity event logs and monitoring management, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '31'),
    ('2-1-P-1-1', 'إدارة الأصول (مقدم الخدمة) - 2-1-P-1-1', 'Inventory of all information and technology assets using suitable techniques such as Configuration Management Database (CMDB) or similar capability containing an inventory of all technical assets', 'تعزيز الأمن السيبراني', 'فرعي', '32'),
    ('2-1-P-1-2', 'إدارة الأصول (مقدم الخدمة) - 2-1-P-1-2', 'Identifying assets owners and involving them in the asset management lifecycle', 'تعزيز الأمن السيبراني', 'فرعي', '33'),
    ('2-1-T-1', 'إدارة الأصول (المشترك) - 2-1-T-1', 'In addition to controls in the ECC control 2-1, the CST shall cover the following additional controls for cybersecurity requirements for cybersecurity event logs and monitoring management, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '34'),
    ('2-1-T-1-1', 'إدارة الأصول (المشترك) - 2-1-T-1-1', 'Inventory of all cloud services and information and technology assets related to the cloud services.', 'تعزيز الأمن السيبراني', 'فرعي', '35'),
    ('2-2-P-1', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1', 'In addition to Subcontrols in the ECC control 2-2-3, the CSP shall cover the following additional Subcontrols for cybersecurity requirements for identity and access management requirements, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '36'),
    ('2-2-P-1-1', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-1', 'Identity and access management of generic accounts credentials for accountability cannot be assigned for a specific individual', 'تعزيز الأمن السيبراني', 'فرعي', '37'),
    ('2-2-P-1-2', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-2', 'Secure session management, including session authenticity, session lockout, and session timeout termination', 'تعزيز الأمن السيبراني', 'فرعي', '38'),
    ('2-2-P-1-3', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-3', 'Multi-factor authentication for privileged users, and candidates of personnel with access to Cloud Technology Stack', 'تعزيز الأمن السيبراني', 'فرعي', '39'),
    ('2-2-P-1-4', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-4', 'Formal process to detect and prevent unauthorized access (e.g., unsuccessful login attempt threshold)', 'تعزيز الأمن السيبراني', 'فرعي', '40'),
    ('2-2-P-1-5', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-5', 'Utilizing secure methods and algorithms for saving and processing passwords, such as: Secure Hashing functions. مقيد - محدود', 'تعزيز الأمن السيبراني', 'فرعي', '41'),
    ('2-2-P-1-6', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-6', 'Secure management of third- party personnel’s accounts', 'تعزيز الأمن السيبراني', 'فرعي', '42'),
    ('2-2-P-1-7', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-7', 'Access control enforced to management systems, administrative consoles', 'تعزيز الأمن السيبراني', 'فرعي', '43'),
    ('2-2-P-1-8', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-8', 'Masking of displayed authentication inputs, especially passwords, to prevent shoulder surfing', 'تعزيز الأمن السيبراني', 'فرعي', '44'),
    ('2-2-P-1-9', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-9', 'Getting CST’s approval before accessing any CST-related asset by the CSP or CSP’s third parties', 'تعزيز الأمن السيبراني', 'فرعي', '45'),
    ('2-2-P-1-10', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-10', 'Capability to immediately interrupt a remote access session and prevent any future access for a user', 'تعزيز الأمن السيبراني', 'فرعي', '46'),
    ('2-2-P-1-11', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-11', 'Provision to CSTs of multi-factor authentication services for privileged cloud users', 'تعزيز الأمن السيبراني', 'فرعي', '47'),
    ('2-2-P-1-12', 'إدارة هويات الدخول والصلاحيات (مقدم الخدمة) - 2-2-P-1-12', 'Assurance of restricted and controlled access to storage systems and means (such as Storage Area Network (SAN))', 'تعزيز الأمن السيبراني', 'فرعي', '48'),
    ('2-2-T-1', 'إدارة هويات الدخول والصلاحيات (المشترك) - 2-2-T-1', 'In addition to Subcontrols in the ECC control 2-2-3, the CST shall cover the following additional Subcontrols for cybersecurity requirements for identity and access management requirements, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '49'),
    ('2-2-T-1-1', 'إدارة هويات الدخول والصلاحيات (المشترك) - 2-2-T-1-1', 'Identity and access management for all cloud credentials along their full lifecycle', 'تعزيز الأمن السيبراني', 'فرعي', '50'),
    ('2-2-T-1-2', 'إدارة هويات الدخول والصلاحيات (المشترك) - 2-2-T-1-2', 'Confidentiality of cloud user identification, cloud credential and cloud access rights information, including the requirement on users to keep them private (for employed, third party and CST personnel)', 'تعزيز الأمن السيبراني', 'فرعي', '51'),
    ('2-2-T-1-3', 'إدارة هويات الدخول والصلاحيات (المشترك) - 2-2-T-1-3', 'Secure session management, including session authenticity, session lockout, and session timeout termination on the cloud', 'تعزيز الأمن السيبراني', 'فرعي', '52'),
    ('2-2-T-1-4', 'إدارة هويات الدخول والصلاحيات (المشترك) - 2-2-T-1-4', 'Multi-factor authentication for privileged cloud users', 'تعزيز الأمن السيبراني', 'فرعي', '53'),
    ('2-2-T-1-5', 'إدارة هويات الدخول والصلاحيات (المشترك) - 2-2-T-1-5', 'Formal process to detect and prevent unauthorized access to cloud (such as a threshold of unsuccessful login attempts).', 'تعزيز الأمن السيبراني', 'فرعي', '54'),
    ('2-3-P-1', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1', 'In addition to Subcontrols in the ECC control 2-3-3, the CSP shall cover the following additional Subcontrols for cybersecurity requirements for information system and processing facilities protection requirements, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '55'),
    ('2-3-P-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-1', 'Ensuring that all configurations are applied in accordance with CSP’s cybersecurity standards', 'تعزيز الأمن السيبراني', 'فرعي', '56'),
    ('2-3-P-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-2', 'Assurance of separation and isolation of data, environments, and information systems across CSTs, to prevent data commingling', 'تعزيز الأمن السيبراني', 'فرعي', '57'),
    ('2-3-P-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-3', 'Adopting cybersecurity principles for technical system configurations adhering to the minimum functionality principle', 'تعزيز الأمن السيبراني', 'فرعي', '58'),
    ('2-3-P-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-4', 'Ability of the Cloud Technology Stacks to securely handle input validation, exceptions and failure. مقيد - محدود', 'تعزيز الأمن السيبراني', 'فرعي', '59'),
    ('2-3-P-1-5', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-5', 'Full isolation of security functions and applications from other functions and applications in the Cloud Technology Stack', 'تعزيز الأمن السيبراني', 'فرعي', '60'),
    ('2-3-P-1-6', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-6', 'Notification to CSTs with cybersecurity requirements provided by the CSP that are useable by the CST', 'تعزيز الأمن السيبراني', 'فرعي', '61'),
    ('2-3-P-1-7', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-7', 'Detection and prevention of unauthorized changes to software programs, and systems', 'تعزيز الأمن السيبراني', 'فرعي', '62'),
    ('2-3-P-1-8', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-8', 'Complete isolation and protection of multiple guest environments', 'تعزيز الأمن السيبراني', 'فرعي', '63'),
    ('2-3-P-1-9', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-9', 'The community cloud services provided to CSTs (government entities and CNI entities) shall be isolated from any other cloud computing provided to entities outside the scope of work', 'تعزيز الأمن السيبراني', 'فرعي', '64'),
    ('2-3-P-1-10', 'حماية الأنظمة وأجهزة معالجة المعلومات (مقدم الخدمة) - 2-3-P-1-10', 'Modern technologies, such as Endpoint Detection and Response (EDR) technologies, to ensure that the information servers and devices of CSP’s information processing systems and devices of are ready for rapid response to incidents', 'تعزيز الأمن السيبراني', 'فرعي', '65'),
    ('2-3-T-1', 'حماية الأنظمة وأجهزة معالجة المعلومات (المشترك) - 2-3-T-1', 'In addition to Subcontrols in the ECC control 2-3-3, the CST shall cover the following additional Subcontrols for cybersecurity requirements for information system and processing facilities protection requirements, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '66'),
    ('2-3-T-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات (المشترك) - 2-3-T-1-1', 'Verifying that the CSP isolates the community cloud services provided to CSTs (government entities and CNI entities) from any other cloud computing provided to entities outside the scope of work.', 'تعزيز الأمن السيبراني', 'فرعي', '67'),
    ('2-4-P-1', 'إدارة أمن الشبكات (مقدم الخدمة) - 2-4-P-1', 'In addition to Subcontrols in the ECC control 2-5-3, the CSP shall cover the following additional Subcontrols for cybersecurity requirements for networks security management requirements, as a minimum:', 'تعزيز الأمن السيبراني', 'أساسي', '68'),
    ('2-4-P-1-1', 'إدارة أمن الشبكات (مقدم الخدمة) - 2-4-P-1-1', 'Monitoring of traffic across the external and internal networks to detect anomalies', 'تعزيز الأمن السيبراني', 'فرعي', '69'),
    ('2-4-P-1-2', 'إدارة أمن الشبكات (مقدم الخدمة) - 2-4-P-1-2', 'Network isolation and protection of Cloud Technology Stack network from other internal and external networks', 'تعزيز الأمن السيبراني', 'فرعي', '70'),
    ('2-4-P-1-3', 'إدارة أمن الشبكات (مقدم الخدمة) - 2-4-P-1-3', 'Protection from denial-of-service attacks (including Distributed Denial of Service (DDoS))', 'تعزيز الأمن السيبراني', 'فرعي', '71'),
